from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

import pandas as pd
import pdfplumber
from rapidfuzz import fuzz, process

INVOICES_PDF='/root/invoices.pdf'
VENDORS_XLSX='/root/vendors.xlsx'
PO_CSV='/root/purchase_orders.csv'
OUT_JSON='/root/fraud_report.json'

money_re=re.compile(r"(?:Total\s*\$\s*)([0-9][0-9,]*\.?[0-9]{0,2})", re.IGNORECASE)
vendor_re=re.compile(r"^From:\s*(.+?)\s*$", re.IGNORECASE|re.MULTILINE)
iban_re=re.compile(r"Payment\s+IBAN:\s*([A-Z0-9_]+)", re.IGNORECASE)
po_re=re.compile(r"PO\s+Number:\s*([A-Z0-9\-]+)", re.IGNORECASE)


def norm_name(s: str) -> str:
    s=s.lower().strip()
    s=re.sub(r"[\.,]", " ", s)
    s=re.sub(r"\s+", " ", s)
    repl={
        " limited":" ltd",
        " ltd":" ltd",
        " corporation":" corp",
        " corp":" corp",
        " incorporated":" inc",
        " inc":" inc",
        " company":" co",
        " co":" co",
    }
    for k,v in repl.items():
        s=s.replace(k,v)
    s=re.sub(r"\s+", " ", s).strip()
    return s


def norm_iban(s: str|None) -> str|None:
    if s is None:
        return None
    return re.sub(r"\s+", "", s).upper().strip()


def parse_money(s: str|None) -> Decimal|None:
    if not s:
        return None
    s=s.replace(',', '').strip()
    try:
        return Decimal(s)
    except InvalidOperation:
        return None


def dec_to_float_2(d: Decimal) -> float:
    q=d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return float(q)


vendors_df=pd.read_excel(VENDORS_XLSX, dtype=str).fillna('')
vendors=[]
name_choices=[]
for _,row in vendors_df.iterrows():
    vid=row['id'].strip()
    name=row['name'].strip()
    iban=norm_iban(row['iban'])
    n=norm_name(name)
    vendors.append({'id':vid,'name':name,'name_norm':n,'iban':iban})
    name_choices.append(n)

po_df=pd.read_csv(PO_CSV, dtype=str).fillna('')
pos_by_number={}
for _,row in po_df.iterrows():
    po=row['po_number'].strip()
    pos_by_number[po]={
        'po_number':po,
        'vendor_id':row['vendor_id'].strip(),
        'amount':parse_money(row['amount'].strip())
    }


def match_vendor(extracted_name: str):
    n=norm_name(extracted_name)
    # get top 2 for ambiguity handling
    matches=process.extract(n, name_choices, scorer=fuzz.token_sort_ratio, limit=2)
    # matches: [(choice, score, idx), ...]
    if not matches:
