    second_score=matches[1][1] if len(matches)>1 else 0
    # Conservative acceptance: allow small typos/variations
    if best_score < 85 or (best_score - second_score) < 3:
        return None
    return vendors[best_idx] | {'score': best_score, 'extracted_norm': n}


flagged=[]

with pdfplumber.open(INVOICES_PDF) as pdf:
    for page_idx, page in enumerate(pdf.pages, start=1):
        text=(page.extract_text() or '').strip()

        vm=vendor_re.search(text)
        vendor_name=(vm.group(1).strip() if vm else '')

        mm=money_re.search(text)
        amount=parse_money(mm.group(1) if mm else None)

        im=iban_re.search(text)
        iban=norm_iban(im.group(1) if im else None)

        pm=po_re.search(text)
        po_number=(pm.group(1).strip() if pm else None)

        vendor_match=match_vendor(vendor_name) if vendor_name else None

        reason=None
        if vendor_match is None:
            reason='Unknown Vendor'
        else:
            vendor_id=vendor_match['id']
            vendor_iban=vendor_match['iban']
            if iban is not None and vendor_iban is not None and iban != vendor_iban:
                reason='IBAN Mismatch'
            else:
                if po_number is not None and po_number not in pos_by_number:
                    reason='Invalid PO'
                else:
                    if po_number is not None:
                        po_rec=pos_by_number[po_number]
                        po_amount=po_rec['amount']
                        if amount is not None and po_amount is not None:
                            if (amount - po_amount).copy_abs() > Decimal('0.01'):
                                reason='Amount Mismatch'
                        if reason is None:
                            if po_rec['vendor_id'] and po_rec['vendor_id'] != vendor_id:
                                reason='Vendor Mismatch'

        if reason is not None:
            flagged.append({
                'invoice_page_number': page_idx,
                'vendor_name': vendor_name or None,
                'invoice_amount': dec_to_float_2(amount) if amount is not None else None,
                'iban': iban,
                'po_number': po_number,
                'reason': reason,
            })

with open(OUT_JSON,'w',encoding='utf-8') as f:
    json.dump(flagged, f, indent=2, ensure_ascii=False)

print('Flagged invoices:', len(flagged))
print('Wrote:', OUT_JSON)
# quick sanity preview
print('First 5 flagged:')
for r in flagged[:5]:
    print(r)
