def norm_name(s: str) -> str:
    s=s.lower().strip()
    s=re.sub(r"[\.,]", " ", s)
    s=re.sub(r"\s+", " ", s)
    repl={
        " limited":" ltd",
        " ltd":" ltd",
        " corporation":" corp",
        " corp":" corp",
        " incorporated":" inc",
        " inc":" inc",
        " company":" co",
        " co":" co",
    }
    for k,v in repl.items():
